import manifest from './image-manifest.json'

/** Where help images are served from: the `public/help` folder, at the site root. */
export const HELP_IMAGE_BASE = '/help/'

export interface HelpImageSize {
  readonly width: number
  readonly height: number
}

/**
 * Intrinsic size of every image in `public/help`, keyed by file name.
 * Generated by `npm run help:images`; never edited by hand.
 */
export const HELP_IMAGE_MANIFEST: Readonly<Record<string, HelpImageSize>> = manifest

/**
 * The file name behind a help image source, or undefined when the source is not
 * a file directly under `/help/`. Anything else — another site, a nested path —
 * is not a help image, and is treated as absent rather than fetched.
 */
export function helpImageFileName(src: string): string | undefined {
  if (!src.startsWith(HELP_IMAGE_BASE)) return undefined
  const fileName = src.slice(HELP_IMAGE_BASE.length)
  return fileName === '' || fileName.includes('/') ? undefined : fileName
}

/** The size recorded for a source, or undefined when it is not in the manifest. */
export function helpImageSize(src: string): HelpImageSize | undefined {
  const fileName = helpImageFileName(src)
  if (fileName === undefined || !Object.hasOwn(HELP_IMAGE_MANIFEST, fileName)) return undefined
  return HELP_IMAGE_MANIFEST[fileName]
}

export interface HelpImageReference {
  readonly alt: string
  readonly src: string
}

const HTML_COMMENT = /<!--[\s\S]*?-->/g

/* Alt text may hold escapes and balanced brackets: ![the [Pay] button](...) */
const ALT = String.raw`((?:\\.|[^\[\]\\]|\[(?:\\.|[^\[\]\\])*\])*)`
const INLINE = String.raw`\(\s*(?:<([^>]*)>|([^)\s]+))(?:\s+(?:"[^"]*"|'[^']*'))?\s*\)`

/** ![alt](src), ![alt][ref], ![alt][] and ![alt]: the forms Markdown renders as an image. */
const MARKDOWN_IMAGE = new RegExp(String.raw`!\[${ALT}\](?:${INLINE}|\[([^\]]*)\])?`, 'g')

/** `[label]: src` definitions, which reference-style images resolve against. */
const DEFINITION = /^ {0,3}\[([^\]]+)\]:[ \t]*(?:<([^>]*)>|(\S+))/gm

function normaliseLabel(label: string): string {
  return label.trim().replace(/\s+/g, ' ').toLowerCase()
}

/**
 * Every image in a page body, in order, ignoring commented-out ones.
 *
 * This is the authoring gate's view of the page, so it has to see what
 * react-markdown will render: a reference-style image, or an alt containing a
 * bracket, that this missed would reach readers unchecked. A reference with no
 * matching definition renders as literal text, not an image, and is skipped.
 */
export function extractImageReferences(body: string): readonly HelpImageReference[] {
  const text = body.replace(HTML_COMMENT, '')
  const definitions = new Map<string, string>()
  for (const match of text.matchAll(DEFINITION)) {
    const label = normaliseLabel(match[1] ?? '')
    if (!definitions.has(label)) definitions.set(label, match[2] ?? match[3] ?? '')
  }

  const references: HelpImageReference[] = []
  for (const match of text.matchAll(MARKDOWN_IMAGE)) {
    const alt = match[1] ?? ''
    const isInline = match[2] !== undefined || match[3] !== undefined
    const refLabel = match[4] === undefined || match[4] === '' ? alt : match[4]
    const src = isInline ? (match[2] ?? match[3]) : definitions.get(normaliseLabel(refLabel))
    if (src !== undefined) references.push({ alt, src })
  }
  return references
}
